UPDATE t_bank_statement
SET imported_line_count = #{importedLineCount}, duplicate_line_count = #{duplicateLineCount}, reject_reason = #{rejectReason}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = 'RECEIVING'

UPDATE t_bank_statement
SET period_start = #{replacement.periodStart}, period_end = #{replacement.periodEnd}, opening_balance = #{replacement.openingBalance}, closing_balance = #{replacement.closingBalance}, declared_line_count = #{replacement.declaredLineCount}, imported_line_count = 0, duplicate_line_count = 0, file_name = #{replacement.fileName}, file_content_hash = #{replacement.fileContentHash}, reject_reason = NULL, status = 'RECEIVING', maker_id = #{replacement.makerId}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = 'REJECTED'

UPDATE t_bank_statement
SET status = #{status}, reject_reason = #{rejectReason}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = #{record.status}
